const items = $input.all();

if (!items || items.length === 0) {
  return [{ json: { error: 'No data found', questions: [] } }];
}

const questionMap = new Map();

for (const item of items) {
  const data = item.json;
  const questionId = data.question_id;

  if (!questionMap.has(questionId)) {
    questionMap.set(questionId, {
      id: questionId,
      question: data.question,
      date: data.date,
      temperature: data.temperature,
      max_tokens: data.max_tokens,
      responses: []
    });
  }

  if (data.reponse && data.provider) {
    questionMap.get(questionId).responses.push({
      id: data.reponse_id,
      provider: data.provider,
      reponse: data.reponse
    });
  }
}

const questions = Array.from(questionMap.values());
return questions.map(q => ({ json: q }));

const questions = $input.all();

let html = `<!DOCTYPE html>
<html lang="fr">
<head>
  <meta charset="UTF-8">
  <title>Historique Comparateur LLM</title>
  <style>
    body { font-family: 'Segoe UI', Arial, sans-serif; margin: 0; padding: 20px; background: #f0f2f5; }
    h1 { color: #2c3e50; border-bottom: 3px solid #3498db; padding-bottom: 10px; }
    .stats { background: #3498db; color: white; padding: 10px 20px; border-radius: 8px; margin-bottom: 20px; display: inline-block; }
    .question-card { background: white; padding: 25px; margin: 20px 0; border-radius: 10px; box-shadow: 0 2px 8px rgba(0,0,0,0.1); border-left: 5px solid #3498db; }
    .question-text { font-size: 18px; font-weight: bold; color: #2c3e50; margin-bottom: 12px; }
    .metadata { color: #7f8c8d; font-size: 13px; margin-bottom: 18px; }
    .responses-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 15px; }
    .response-card { padding: 15px; background: #f8f9fa; border-radius: 8px; border-top: 3px solid #e74c3c; }
    .provider-badge { font-weight: bold; color: #e74c3c; font-size: 14px; margin-bottom: 8px; }
    .response-text { color: #34495e; font-size: 14px; line-height: 1.6; }
  </style>
</head>
<body>
  <h1>📊 Historique du Comparateur LLM</h1>
  <div class="stats">Total : ${questions.length} question(s) analysée(s)</div>
`;

for (const item of questions) {
  const q = item.json;
  const date = new Date(q.date).toLocaleDateString('fr-FR', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric', hour: '2-digit', minute: '2-digit' });
  html += `
  <div class="question-card">
    <div class="question-text">❓ ${q.question}</div>
    <div class="metadata">📅 ${date} &nbsp;|&nbsp; 🌡️ Température : ${q.temperature || 'N/A'} &nbsp;|&nbsp; 🔢 Max tokens : ${q.max_tokens || 'N/A'}</div>
    <div class="responses-grid">
  `;

  if (q.responses && q.responses.length > 0) {
    for (const resp of q.responses) {
      const excerpt = resp.reponse.length > 400 ? resp.reponse.substring(0, 400) + '...' : resp.reponse;
      html += `
      <div class="response-card">
        <div class="provider-badge">🤖 ${resp.provider}</div>
        <div class="response-text">${excerpt}</div>
      </div>
      `;
    }
  } else {
    html += `<p><em>Aucune réponse enregistrée pour cette question.</em></p>`;
  }

  html += `</div></div>`;
}

html += `</body></html>`;

return [{ json: { html, count: questions.length } }];
